:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8fa3;
  --snake: #4ecca3;
  --snake-head: #7ef0c0;
  --food: #e94560;
  --grid: #1f2b4a;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  max-width: 460px;
  width: 100%;
  box-shadow: 0 10px 40px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.game-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 1px;
  color: var(--snake);
}

.score {
  font-size: 1.1rem;
  font-weight: 600;
  background: rgba(78, 204, 163, 0.15);
  padding: 6px 14px;
  border-radius: 20px;
}

.board-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 10px;
  overflow: hidden;
  background: var(--grid);
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(22, 33, 62, 0.92);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 24px;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
}

.overlay.visible {
  opacity: 1;
  pointer-events: auto;
}

.overlay h2 {
  font-size: 1.4rem;
  color: var(--snake);
}

.overlay p {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text);
}

.overlay strong { color: var(--snake); }

.controls {
  display: flex;
  gap: 12px;
}

.btn {
  flex: 1;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 16px;
  border: 2px solid var(--snake);
  border-radius: 10px;
  background: transparent;
  color: var(--snake);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, transform 0.1s;
}

.btn:hover { background: rgba(78, 204, 163, 0.15); }
.btn:active { transform: scale(0.97); }
.btn:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }

.btn.primary {
  background: var(--snake);
  color: var(--card);
}

.btn.primary:hover { background: var(--snake-head); border-color: var(--snake-head); }

.hint {
  font-size: 0.9rem;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 400px) {
  .game-card { padding: 16px; }
  h1 { font-size: 1.25rem; }
  .overlay p { font-size: 0.95rem; }
}

const canvas = document.getElementById('board');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const overlay = document.getElementById('overlay');
const overlayTitle = document.getElementById('overlayTitle');
const overlayText = document.getElementById('overlayText');
const startBtn = document.getElementById('startBtn');
const pauseBtn = document.getElementById('pauseBtn');
const restartBtn = document.getElementById('restartBtn');

const GRID = 20;
const CELL = canvas.width / GRID;
const TICK = 120;

let snake, dir, nextDir, food, score, state, timer;

function reset() {
  snake = [{x: 10, y: 10}];
  dir = {x: 0, y: 0};
  nextDir = {x: 0, y: 0};
  score = 0;
  scoreEl.textContent = '0';
  placeFood();
  state = 'paused';
  updatePauseBtn();
  draw();
}

function placeFood() {
  do {
    food = { x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID) };
  } while (snake.some(s => s.x === food.x && s.y === food.y));
}

function start() {
  overlay.classList.remove('visible');
  state = 'running';
  updatePauseBtn();
  clearInterval(timer);
  timer = setInterval(tick, TICK);
}

function pause() {
  if (state === 'running') {
    state = 'paused';
    clearInterval(timer);
    updatePauseBtn();
  } else if (state === 'paused') {
    start();
  }
}

function updatePauseBtn() {
  if (state === 'running') {
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-label', 'Pause game');
  } else if (state === 'paused') {
    pauseBtn.textContent = 'Resume';
    pauseBtn.setAttribute('aria-label', 'Resume game');
  } else {
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-label', 'Pause game');
  }
}

function tick() {
  if (state !== 'running') return;
  if (nextDir.x !== 0 || nextDir.y !== 0) {
    if (nextDir.x !== -dir.x || nextDir.y !== -dir.y) dir = nextDir;
  }
  if (dir.x === 0 && dir.y === 0) return;

  const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

  if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID ||
      snake.some(s => s.x === head.x && s.y === head.y)) {
    gameOver();
    return;
  }

  snake.unshift(head);
  if (head.x === food.x && head.y === food.y) {
    score++;
    scoreEl.textContent = score;
    placeFood();
  } else {
    snake.pop();
  }
  draw();
}

function gameOver() {
  state = 'over';
  clearInterval(timer);
  overlayTitle.textContent = 'Game Over';
  overlayText.innerHTML = 'Your score: <strong>' + score + '</strong>';
  startBtn.textContent = 'Play Again';
  overlay.classList.add('visible');
  updatePauseBtn();
  draw();
}

function draw() {
  ctx.fillStyle = '#1f2b4a';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.strokeStyle = '#16213e';
  ctx.lineWidth = 1;
  for (let i = 1; i < GRID; i++) {
    ctx.beginPath();
    ctx.moveTo(i * CELL, 0);
    ctx.lineTo(i * CELL, canvas.height);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, i * CELL);
    ctx.lineTo(canvas.width, i * CELL);
    ctx.stroke();
  }

  ctx.fillStyle = '#e94560';
  ctx.fillRect(food.x * CELL + 2, food.y * CELL + 2, CELL - 4, CELL - 4);

  snake.forEach((seg, i) => {
    ctx.fillStyle = i === 0 ? '#7ef0c0' : '#4ecca3';
    ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
  });
}

function handleKey(e) {
  const key = e.key;
  if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(key)) {
    e.preventDefault();
    if (state === 'paused' && overlay.classList.contains('visible')) return;
    if (state === 'over') return;
    if (key === 'ArrowUp' && dir.y !== 1) nextDir = {x: 0, y: -1};
    if (key === 'ArrowDown' && dir.y !== -1) nextDir = {x: 0, y: 1};
    if (key === 'ArrowLeft' && dir.x !== 1) nextDir = {x: -1, y: 0};
    if (key === 'ArrowRight' && dir.x !== -1) nextDir = {x: 1, y: 0};
    if (state === 'paused') start();
  } else if (key === 'p' || key === 'P') {
    e.preventDefault();
    if (state !== 'over') pause();
  } else if (key === 'r' || key === 'R') {
    e.preventDefault();
    restart();
  }
}

function restart() {
  clearInterval(timer);
  overlayTitle.textContent = 'How to Play';
  overlayText.innerHTML = 'Use the <strong>arrow keys</strong> to move the snake.<br>Eat the food to grow and score points.<br>Don\'t hit the walls or yourself!';
  startBtn.textContent = 'Start Game';
  reset();
  overlay.classList.add('visible');
}

startBtn.addEventListener('click', () => {
  if (state === 'over') restart();
  start();
});
pauseBtn.addEventListener('click', pause);
restartBtn.addEventListener('click', restart);
window.addEventListener('keydown', handleKey);

reset();
